/** Authored mock output: choose an exact visible numeric fact per supplied target. */
export function mockCampaignReadings(context){return context.campaigns.map(c=>{const child=context.role==='creative'&&c.hierarchy?.find(h=>h.rows.some(r=>Number.isFinite(r.spend))),period=child?.period||Object.keys(c.windows).find(p=>Number.isFinite(c.windows[p]?.spend)),row=child?child.rows.find(r=>Number.isFinite(r.spend)):c.windows[period];return {adAccountId:c.target.adAccountId,externalId:c.target.externalId,assessment:'observe',reason:'Conferir nova aquisição deste objeto.',citations:row?[{period,level:child?.level||'campaign',externalId:child?row.externalId:c.target.externalId,metric:'spend',value:row.spend}]:[]};});}
